// AccountWarning A warning as its user sees it. It holds no note and names no administrator.
type AccountWarning struct {
	Acknowledged bool `json:"acknowledged"`

	// AcknowledgedAt When the user first acknowledged it; null until then.
	AcknowledgedAt *time.Time         `json:"acknowledgedAt"`
	CreatedAt      time.Time          `json:"createdAt"`
	Id             openapi_types.UUID `json:"id"`
	Reason         string             `json:"reason"`
}

// AccountWarningList defines model for AccountWarningList.
type AccountWarningList struct {
	Items []AccountWarning `json:"items"`
}

// AddGroupMembersRequest defines model for AddGroupMembersRequest.
type AddGroupMembersRequest struct {
	// UserIds 1 to 49 users, not the caller.
	UserIds []openapi_types.UUID `json:"userIds"`
}

// AddLinkRequest defines model for AddLinkRequest.
type AddLinkRequest struct {
	// Kind What a profile link points to; the client shows a label and icon for it.
	Kind LinkKind `json:"kind"`

	// Url An https URL with a host, without whitespace, at most 300 characters after trimming.
	Url string `json:"url"`
}

// AddTagRequest defines model for AddTagRequest.
type AddTagRequest struct {
	// Name Trimmed, and every run of spaces, tabs or line breaks becomes one space; then 1 to
	// 60 characters.
	//
	//
	// Example: Machine Learning
	Name string `json:"name"`
}

// AdminUser One user account as an administrator sees it.
type AdminUser struct {
	CreatedAt time.Time          `json:"createdAt"`
	Email     string             `json:"email"`
	FullName  string             `json:"fullName"`
	Id        openapi_types.UUID `json:"id"`

	// Role The platform role (SRS 2.2). Administrators are made only from the command line
	// (`make admin`); no operation changes a role.
	Role Role `json:"role"`

	// Suspended The account is suspended now (FR-3.4). A suspension that has ended by time reads
	// false, also before the user's next login clears it.
	Suspended bool `json:"suspended"`

	// SuspendedUntil When a temporary suspension ends. Null unless `suspended` is true, and when it is permanent.
	SuspendedUntil *time.Time `json:"suspendedUntil"`

	// SuspensionReason What the user was told. Null unless `suspended` is true, and for an account
	// suspended before reasons were recorded.
	SuspensionReason *string `json:"suspensionReason"`

	// Verified The email address is verified (FR-1.4).
	Verified bool `json:"verified"`
}

// Attachment defines model for Attachment.
type Attachment struct {
	// ContentType The type found from the content, one of the allowed types.
	ContentType string `json:"contentType"`

	// Id Download it with `GET /attachments/{id}`.
	Id openapi_types.UUID `json:"id"`

	// Name The file's name for display, cleaned up; at most 200 characters.
	Name string `json:"name"`

	// Size Bytes as stored (an image after it was encoded again).
	Size int64 `json:"size"`

	// Status The malware scan (FR-16.7). `pending`: not scanned yet; nobody can download it.
	// `clean`: it can be downloaded. `infected`: malware was found and the file deleted.
	// `failed`: the scanner could not read the file; it will not be served.
	Status AttachmentStatus `json:"status"`
}

// AttachmentStatus The malware scan (FR-16.7). `pending`: not scanned yet; nobody can download it.
// `clean`: it can be downloaded. `infected`: malware was found and the file deleted.
// `failed`: the scanner could not read the file; it will not be served.
type AttachmentStatus string

// AttachmentUpload defines model for AttachmentUpload.
type AttachmentUpload struct {
	ContentType string `json:"contentType"`

	// ExpiresAt The attachment is deleted when it has not been sent by then.
	ExpiresAt time.Time          `json:"expiresAt"`
	Id        openapi_types.UUID `json:"id"`
	Name      string             `json:"name"`
	Size      int64              `json:"size"`

	// Status The malware scan (FR-16.7). `pending`: not scanned yet; nobody can download it.
	// `clean`: it can be downloaded. `infected`: malware was found and the file deleted.
	// `failed`: the scanner could not read the file; it will not be served.
	Status AttachmentStatus `json:"status"`
}

